userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span style="font-weight:600">Emphasize construction</span><span><button id="completeBtn" onclick="setEmphasis('complete')">Complete</button> <button id="additionBtn" onclick="setEmphasis('addition')">u + v</button> <button id="subtractionBtn" onclick="setEmphasis('subtraction')">u − v</button></span><span id="demoNarration" style="margin:0;font-size:10px;line-height:1.35;max-width:260px">The default view is the completed textbook figure: addition and subtraction parallelograms are both visible side by side, with all component and resultant arrows already labeled.</span><span><button onclick="prevStep()">◀</button> <span id="stepLabel">1 / 3 Completed comparison</span> <button onclick="nextStep()">▶</button></span><span style="font-size:10px;color:#555;line-height:1.35">Click either parallelogram or diagonal to focus that construction.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var container = document.getElementById('container');
var draw = SVG().addTo(container).size('100%', '100%');
var W = 600, H = 165;
draw.viewbox(0, 0, W, H);

var blue = '#154b7a';
var blueThin = '#1b4f82';
var orange = '#f05a24';
var halo = '#ffd66b';
var labelFill = '#111111';

draw.rect(W, H).fill('#ffffff');

var arrowOrange = draw.marker(9, 9, function (add) {
  add.path('M 0 0 L 9 4.5 L 0 9 Z').fill(orange).stroke('none');
}).ref(8.2, 4.5).orient('auto');
arrowOrange.attr({ markerUnits: 'userSpaceOnUse' });

var gHalo = draw.group();
var gOutline = draw.group();
var gThin = draw.group();
var gActive = draw.group();
var gLabels = draw.group();
var gHit = draw.group();

var panels = {
  addition: {
    key: 'addition',
    A: { x: 12, y: 132 },
    B: { x: 148, y: 132 },
    C: { x: 220, y: 28 },
    D: { x: 84, y: 28 }
  },
  subtraction: {
    key: 'subtraction',
    A: { x: 252, y: 132 },
    B: { x: 388, y: 132 },
    C: { x: 460, y: 28 },
    D: { x: 324, y: 28 }
  }
};

var currentEmphasis = 'complete';
var currentStep = 0;

var demoSteps = [
  {
    title: 'Completed comparison',
    narration: 'The default view is the completed textbook figure: addition and subtraction parallelograms are both visible side by side, with all component and resultant arrows already labeled.',
    state: { constructionEmphasis: 'complete' }
  },
  {
    title: 'Read the addition panel',
    narration: 'In the left panel, u is followed by v, so the resultant u + v is the diagonal from the starting tail to the final head.',
    state: { constructionEmphasis: 'addition' }
  },
  {
    title: 'Read the subtraction panel',
    narration: 'In the right panel, subtraction is shown as u plus the opposite vector -v, so u - v is the diagonal from the starting tail to the head of -v.',
    state: { constructionEmphasis: 'subtraction' }
  }
];

function seg(group, p, q, color, width, opacity) {
  return group.line(p.x, p.y, q.x, q.y).stroke({
    color: color,
    width: width,
    opacity: opacity == null ? 1 : opacity,
    linecap: 'round',
    linejoin: 'round'
  });
}

function orangeArrow(p, q) {
  return seg(gActive, p, q, orange, 2.25, 1).marker('end', arrowOrange);
}

function blueResultant(p, q) {
  return seg(gThin, p, q, blueThin, 1.15, 1).marker('end', arrowOrange);
}

function label(txt, x, y, opts) {
  opts = opts || {};
  var t = gLabels.text(txt).font({
    family: 'Arial, Helvetica, sans-serif',
    size: opts.size || 15,
    style: 'italic',
    weight: opts.weight || 600,
    anchor: opts.anchor || 'middle'
  }).attr({
    x: x,
    y: y,
    fill: opts.fill || labelFill,
    stroke: '#ffffff',
    'stroke-width': opts.halo == null ? 2.4 : opts.halo,
    'paint-order': 'stroke',
    'stroke-linejoin': 'round',
    'dominant-baseline': 'middle'
  });
  if (opts.rotate) t.rotate(opts.rotate, x, y);
  return t;
}

function outlinePanel(P) {
  var s = [P.A, P.B, P.C, P.D, P.A].map(function (p) {
    return p.x + ',' + p.y;
  }).join(' ');
  gOutline.polyline(s).fill('none').stroke({
    color: blue,
    width: 2.75,
    linecap: 'round',
    linejoin: 'round'
  });
}

function panelHalo(P) {
  var xs = [P.A.x, P.B.x, P.C.x, P.D.x];
  var ys = [P.A.y, P.B.y, P.C.y, P.D.y];
  var minX = Math.min.apply(null, xs) - 6;
  var maxX = Math.max.apply(null, xs) + 6;
  var minY = Math.min.apply(null, ys) - 6;
  var maxY = Math.max.apply(null, ys) + 6;
  gHalo.rect(maxX - minX, maxY - minY).move(minX, minY).radius(6)
    .fill('none')
    .stroke({ color: halo, width: 3.2, opacity: 0.42, linecap: 'round', linejoin: 'round' });
}

function pathHalo(points) {
  for (var i = 0; i < points.length - 1; i++) {
    seg(gHalo, points[i], points[i + 1], halo, 5.5, 0.34);
  }
}

function drawAddition(P) {
  outlinePanel(P);
  seg(gThin, P.D, P.B, blueThin, 0.95, 0.7);
  blueResultant(P.A, P.C);
  orangeArrow(P.A, P.B);
  orangeArrow(P.B, P.C);

  label('u', 82, 148, { size: 15 });
  label('v', 183, 102, { size: 15 });
  label('u + v', 130, 73, { size: 15, rotate: -25 });
}

function drawSubtraction(P) {
  outlinePanel(P);
  seg(gThin, P.A, P.C, blueThin, 0.95, 0.7);
  blueResultant(P.D, P.B);
  orangeArrow(P.D, P.C);
  orangeArrow(P.C, P.B);

  label('u', 392, 13, { size: 15 });
  label('−v', 430, 98, { size: 15 });
  label('u − v', 363, 75, { size: 15, rotate: 49 });
}

function addHitRegion(P, key) {
  var polyPts = [P.A, P.B, P.C, P.D].map(function (p) { return p.x + ',' + p.y; }).join(' ');
  var panelHit = gHit.polygon(polyPts).fill({ color: '#000000', opacity: 0.001 }).stroke('none');
  panelHit.css('cursor', 'pointer');
  panelHit.on('mousemove', function (e) {
    showTooltip(key === 'addition' ? 'Focus the u + v parallelogram' : 'Focus the u − v parallelogram', e);
  });
  panelHit.on('mouseleave', function () { hideTooltip(); });
  panelHit.on('click', function () { focusPanel(key); });

  var d0 = key === 'addition' ? P.A : P.D;
  var d1 = key === 'addition' ? P.C : P.B;
  var diagHit = gHit.line(d0.x, d0.y, d1.x, d1.y)
    .stroke({ color: '#000000', width: 16, opacity: 0.001, linecap: 'round' });
  diagHit.css('cursor', 'pointer');
  diagHit.on('mousemove', function (e) {
    showTooltip(key === 'addition' ? 'Resultant diagonal u + v' : 'Resultant diagonal u − v', e);
  });
  diagHit.on('mouseleave', function () { hideTooltip(); });
  diagHit.on('click', function () { focusPanel(key); });
}

function drawAll() {
  gHalo.clear();
  gOutline.clear();
  gThin.clear();
  gActive.clear();
  gLabels.clear();
  gHit.clear();

  var L = panels.addition;
  var R = panels.subtraction;

  if (currentEmphasis === 'addition') {
    panelHalo(L);
    pathHalo([L.A, L.B, L.C]);
    pathHalo([L.A, L.C]);
  }
  if (currentEmphasis === 'subtraction') {
    panelHalo(R);
    pathHalo([R.D, R.C, R.B]);
    pathHalo([R.D, R.B]);
  }

  drawAddition(L);
  drawSubtraction(R);
  addHitRegion(L, 'addition');
  addHitRegion(R, 'subtraction');
  updateUi();
}

function stateToStep(state) {
  for (var i = 0; i < demoSteps.length; i++) {
    if (demoSteps[i].state.constructionEmphasis === state) return i;
  }
  return currentStep;
}

function setEmphasis(state, keepStep) {
  if (state !== 'complete' && state !== 'addition' && state !== 'subtraction') return;
  currentEmphasis = state;
  if (!keepStep) currentStep = stateToStep(state);
  drawAll();
}

function focusPanel(key) {
  setEmphasis(key);
  if (key === 'addition') {
    showPopup('Addition: u + v', 'Follow u along the lower edge and then v up the right slanted edge. The diagonal from the first tail to the final head gives the vector u + v.');
  } else {
    showPopup('Subtraction: u − v', 'Subtraction is drawn by replacing v with the opposite vector −v. With u followed by −v, the completed diagonal gives u − v.');
  }
}

function updateUi() {
  ['complete', 'addition', 'subtraction'].forEach(function (id) {
    var b = document.getElementById(id + 'Btn');
    if (b) b.classList.toggle('active', currentEmphasis === id);
  });
  var stepLabel = document.getElementById('stepLabel');
  if (stepLabel) stepLabel.textContent = (currentStep + 1) + ' / ' + demoSteps.length + ' ' + demoSteps[currentStep].title;
  var nar = document.getElementById('demoNarration');
  if (nar) nar.textContent = demoSteps[currentStep].narration;
}

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  currentEmphasis = demoSteps[currentStep].state.constructionEmphasis;
  drawAll();
}

function prevStep() {
  applyStep(currentStep - 1);
}

function nextStep() {
  applyStep(currentStep + 1);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original static 2D figure, making a generation plan, generating an interactive 2D figure (SVG.js / Chart.js / Mermaid), and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

Example 1 → pass
{"failure_modes":["Color-Wrong","Missing-Labels"],"geometry_accuracy":4,"interactivity_usability":4,"faithfulness":3,"label_quality":3,"concept_accuracy":4,"overall_average":3.6,"notes":"Interactive elements are mostly functional, but visual and label details do not fully align with the source."}
{"next_step":"pass","rationale":"Scores are consistently high (mostly 4s), failure modes are minor visual polish issues, and concept and interactivity are solid — further iteration is unlikely to yield meaningful improvement."}

Example 2 → refine_generation
{"failure_modes":["Color-Wrong","Scale-Wrong","Interaction-Missing","Camera-Wrong"],"geometry_accuracy":3,"interactivity_usability":3,"faithfulness":3,"label_quality":3,"concept_accuracy":3,"overall_average":3,"notes":"The rendering contains overlapping text, varying colors, and lacks precise interactivity, making it somewhat difficult to grasp the 3D representation."}
{"next_step":"refine_generation","rationale":"The concept is present but execution has multiple implementation-level issues — color mismatches, missing interactions, wrong camera angle, scale errors — all fixable by the generator without changing the plan."}

Example 3 → fix_plan
{"failure_modes":["Missing-Labels","Interaction-Missing","Camera-Wrong","Color-Wrong","Concept-Misunderstood"],"geometry_accuracy":2,"interactivity_usability":2,"faithfulness":2,"label_quality":2,"concept_accuracy":2,"overall_average":2,"notes":"Discrepancies in elements and labels, with limited interactivity and conceptual errors."}
{"next_step":"fix_plan","rationale":"Concept-Misunderstood failure mode and all scores at 2/5 indicate the plan failed to correctly decompose the figure — the generator cannot fix a fundamentally wrong conceptual structure."}
